momentum = (adcs_vec3_t){0, 0, 0};
hm_ret = adcs_wheel_momentum(wm_input.wheels, wm_input.count, &momentum);
if (hm_ret != ADCS_OK) {
    wm_state.mode = WM_FAULT;
    wm_state.good = 0U;
    wm_output.mode = WM_FAULT;
    wm_output.good = 0U;
    wm_output.momentum = (adcs_vec3_t){0, 0, 0};
    wm_output.error = (adcs_vec3_t){0, 0, 0};
    wm_output.error_norm = 0.0;
    wm_output.error_energy = 0.0;
    return;
}

/* 减 target 得到误差 */
error = adcs_vec3_sub(&momentum, &wm_config.target);

/* linked norm / dot 发布范数与能量 */
norm = adcs_vec3_norm(&error);
energy = adcs_vec3_dot(&error, &error);

wm_output.momentum = momentum;
wm_output.error = error;
wm_output.error_norm = norm;
wm_output.error_energy = energy;

/* 完成状态迁移（每次调用都判定 enable==0 顶层规则） */
if (wm_input.enable == 0) {
    wm_state.mode = WM_ACTIVE;
    wm_state.good = 0U;
} else {
    switch (wm_state.mode) {
    case WM_ACTIVE:
        if (norm <= wm_config.stop) {
            wm_state.good += 1U;
            if (wm_state.good >= wm_config.required) {
                wm_state.mode = WM_COMPLETE;
            } else {
                wm_state.mode = WM_ACTIVE;
            }
        } else {
            wm_state.mode = WM_ACTIVE;
            wm_state.good = 0U;
        }
        break;
    case WM_COMPLETE:
        if (norm < wm_config.restart) {
            wm_state.mode = WM_COMPLETE;
            /* good 保留 */
        } else {
            wm_state.mode = WM_ACTIVE;
            wm_state.good = 0U;
        }
        break;
    case WM_FAULT:
    default:
        wm_state.mode = WM_FAULT;
        wm_state.good = 0U;
        break;
    }
}

wm_output.mode = wm_state.mode;
wm_output.good = wm_state.good;

